update public.checkpoints set description=$$Ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại đây; Lăng khánh thành năm 1975. Quảng trường, Lăng, Phủ Chủ tịch, Nhà sàn và ao cá tạo thành quần thể lịch sử. Fun fact: trước 1945 khu vực được gọi là Vườn hoa Ba Đình. To-do: check-in, quan sát Lăng từ khu vực được phép, tham quan quần thể.$$, icon='📍', badge='Ba Đình', latitude=21.03575, longitude=105.83416 where name='Quảng trường Ba Đình – Lăng Chủ tịch Hồ Chí Minh';
insert into public.checkpoints (name,description,icon,badge,longitude,latitude) select 'Quảng trường Ba Đình – Lăng Chủ tịch Hồ Chí Minh',$$Ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại đây; Lăng khánh thành năm 1975. Quảng trường, Lăng, Phủ Chủ tịch, Nhà sàn và ao cá tạo thành quần thể lịch sử. Fun fact: trước 1945 khu vực được gọi là Vườn hoa Ba Đình. To-do: check-in, quan sát Lăng từ khu vực được phép, tham quan quần thể.$$,'📍','Ba Đình',105.83416,21.03575 where not exists (select 1 from public.checkpoints where name='Quảng trường Ba Đình – Lăng Chủ tịch Hồ Chí Minh');

update public.checkpoints set description=$$Hồ có các tên Lục Thủy, Tả Vọng, Hữu Vọng; tên Hoàn Kiếm gắn với truyền thuyết Lê Lợi trả gươm. Điểm nổi bật: Tháp Rùa, Đền Ngọc Sơn, Tháp Bút, Đài Nghiên, cầu Thê Húc. Fun fact: Tháp Rùa không phải nơi thờ Rùa Vàng. To-do: đi bộ quanh hồ, Đền Ngọc Sơn, phố đi bộ.$$, icon='🌊', badge='Hoàn Kiếm', latitude=21.02877, longitude=105.85058 where name='Hồ Hoàn Kiếm';
