update public.checkpoints set description=$$Gắn với việc Hồ Chí Minh trở về nước năm 1941 và hoạt động cách mạng tại Cao Bằng. Nổi bật với suối Lê-nin, núi Các Mác và hang Pác Bó. To-do: tham quan khu di tích và tìm hiểu lịch sử.$$, icon='🏞️', badge='Pác Bó', latitude=22.97783, longitude=106.05122 where name='Khu di tích Pác Bó';
